def ctest(x, y, n=5000):
    c = np.corrcoef(x, y)[0, 1]
    null = np.array([np.corrcoef(x, rng.permutation(y))[0, 1] for _ in range(n)])
    return c, np.mean(np.abs(null) >= abs(c))
